// Block (composition) — profile identity fields with an avatar preview.
// Arranges only; composes Form/Avatar/TextField/Button/Alert/Stack.
import type { FormEvent, Ref } from "react";
import { Form } from "../components/Form";
import { Avatar } from "../components/Avatar";
import { TextField } from "../components/TextField";
import { Button } from "../components/Button";
import { Alert } from "../components/Alert";
import { Stack } from "../layouts/Stack";
import "./ProfileForm.css";

export interface ProfileFormProps {
  /** Heading shown above the profile fields. */
  heading?: string;
  /** Initial full name. */
  name?: string;
  /** Initial email address. */
  email?: string;
  /** Image used by the avatar preview. */
  avatarSrc?: string;
  /** Called with the submitted identity fields. */
  onSubmit?: (data: Record<string, string>) => void;
  /** Form-level error, shown above the fields. */
  errorMessage?: string;
  /** Puts the submit button in a pending state and blocks re-submit. */
  isPending?: boolean;
  className?: string;
  ref?: Ref<HTMLFormElement>;
}

export function ProfileForm({
  heading,
  name,
  email,
  avatarSrc,
  onSubmit,
  errorMessage,
  isPending,
  className,
  ref,
}: ProfileFormProps) {
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    onSubmit?.({
      name: String(data.get("name") ?? ""),
      email: String(data.get("email") ?? ""),
    });
  };
  const avatarFallback =
    name
      ?.trim()
      .split(/\s+/)
      .map((part) => part[0])
      .slice(0, 2)
      .join("")
      .toUpperCase() || "P";

  return (
    <Form isPending={isPending}
      ref={ref}
      onSubmit={handleSubmit}
      className={className ? `sd-profileform ${className}` : "sd-profileform"}
    >
      <Stack gap="large" className="sd-profileform__content">
        {heading && (
          <>
            <h1 className="sd-profileform__heading sd-type-headline-medium">{heading}</h1>
          </>
        )}
        {/* live="assertive": see `AlertProps.live` — submit failure is the case that earns it. */}
        {errorMessage && (
          <Alert variant="error" live="assertive">
            {errorMessage}
          </Alert>
        )}
        <Avatar
          src={avatarSrc}
          alt={name ? `${name} profile photo` : "Profile photo"}
          size="large"
          className="sd-profileform__avatar"
        >
          {avatarFallback}
        </Avatar>
        <Stack gap="medium" className="sd-profileform__fields">
          <TextField
            label="Full name"
            name="name"
            defaultValue={name}
            autoComplete="name"
            isRequired
          />
          <TextField
            label="Email"
            name="email"
            type="email"
            defaultValue={email}
            autoComplete="email"
            isRequired
          />
        </Stack>
        <Button size="large" type="submit" variant="primary" isPending={isPending}>
          Save
        </Button>
      </Stack>
    </Form>
  );
}

/* ProfileForm.css — arrangement only; Component look stays with its owners. */
/* Fills the column it is given. The page narrows that column on the grid (a Container span), so the
   form's edges land on column lines; a px measure here would leave them off the grid. */
.sd-profileform {
  width: 100%;
}

.sd-profileform__heading {
  margin: 0;
}

.sd-profileform__avatar {
  margin-inline: auto;
}
